function _mAvHTML(src,which,size){let inner;if(isImg(src))inner=`<img src="${src}" style="width:100%;height:100%;object-fit:cover">`;else if(isStoredImgRef(src)){const key=src.slice(4),cached=_imgCache[key];inner=cached?`<img src="${cached}" style="width:100%;height:100%;object-fit:cover">`:`<div data-idb-avatar="${esc(key)}" style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#9ec5fe,#b8a4e3)">${_avIc('user')}</div>`;}else inner=`<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:${Math.round(size*0.5)}px;background:linear-gradient(135deg,#9ec5fe,#b8a4e3)">${esc(src||'🙂')}</div>`;
  return `<div data-music-avatar onclick="setMusicAvatar('${which}')" style="width:${size}px;height:${size}px;border-radius:50%;overflow:hidden;border:2px solid rgba(255,255,255,.9);box-shadow:0 3px 10px rgba(0,0,0,.55);cursor:pointer">${inner}</div>`;}
function setMusicAvatar(which){pickFile('image/*',async f=>{const img=await compress(f,300,.8);musicInit();if(which==='me')S.music.meAvatar=img;else S.music.taAvatar=img;save();render();toast('头像换好了');});}
function setMusicCover(){musicInit();const s=S.music.songs.find(x=>x.id===_mCur);if(!s){toast('先放一首歌');return;}pickFile('image/*',async f=>{s.cover=await compress(f,520,.72);save();render();toast('封面换好了🎵');});}
function setMusicBg(){pickFile('image/*',async f=>{musicInit();S.music.bg=await compressBackground(f);save();closeModal();if(musicEnsureCurrent())_mView='player';render();toast('播放页和音乐首页背景已更换🖼️');});}
function musicDistanceValue(value){const raw=String(value==null?'':value).trim(),n=Number(raw);if(!raw||!Number.isFinite(n)||n<0)return null;return Math.round(n*10)/10;}
function musicDistanceText(value){const n=musicDistanceValue(value);return String(n==null?1400:n);}
function musicSetDistance(value){musicInit();const n=musicDistanceValue(value),input=document.getElementById('musicDistanceInput');if(n==null){if(input)input.value=musicDistanceText(S.music.distance);toast('请输入不小于 0 的有效距离');return false;}S.music.distance=n;save();if(input)input.value=musicDistanceText(n);const display=document.getElementById('musicDistanceValue');if(display)display.textContent=musicDistanceText(n);toast('距离已设为 '+musicDistanceText(n)+' 公里');return true;}
function editMusicDistance(){musicInit();const v=prompt('相距多少公里？',musicDistanceText(S.music.distance));if(v==null)return;musicSetDistance(v);}
function musicLibraryRowHTML(s,scope){const cover=s.cover?`background-image:url(${s.cover})`:'',initial=esc(Array.from(s.title||'音')[0]||'音'),playing=s.id===_mCur,back=scope==='menu'?'menu':'list',source=musicSongSourceLabel(s,s.provider==='audius'?'在线曲库':(s.lyrics?'已添加歌词':'暂无歌词'));return `<article class="music-library-row${playing?' current':''}"><button class="music-library-cover" style="${cover}" onclick="closeModal();musicOpenPlayer('${s.id}',true)" aria-label="播放 ${esc(s.title||'未命名')}">${s.cover?'':`<span>${initial}</span>`}<i>${SVG_PLAY}</i></button><div class="music-library-copy" onclick="closeModal();musicOpenPlayer('${s.id}',true)"><b>${esc(s.title||'未命名')}${playing?'<em>正在播放</em>':''}</b><span>${esc(s.artist||'未知歌手')}<i>${source}</i></span>${roleSongProgressHTML(s)}</div><div class="music-library-actions"><button onclick="musicSync('${s.id}')" title="歌词打轴" aria-label="歌词打轴">${svgIc('clock',15,'currentColor')}</button><button onclick="musicEdit('${s.id}')" title="编辑歌曲" aria-label="编辑歌曲">${svgIc('edit',15,'currentColor')}</button><button class="danger" onclick="musicDel('${s.id}','${back}')" title="删除歌曲" aria-label="删除歌曲">${svgIc('trash',15,'currentColor')}</button></div></article>`;}
function musicChatContacts(){musicInit();return (S.contacts||[]).filter(c=>c&&!c.deleted);}
function musicChatRows(cid){const allowed=new Set(musicChatContacts().map(c=>c.id));return (S.music.chat||[]).filter(m=>allowed.has(m.cid)&&(!cid||m.cid===cid));}
